function replaceContent(node, ...children) { node.replaceChildren(...children.flat(Infinity).filter((child) => child !== null && child !== undefined && child !== false)); }
function clockNow() { return globalThis.performance?.now?.() ?? Date.now(); }
function wallNow() { return Date.now(); }
function cleanText(value) { return String(value ?? '').normalize('NFKC').trim().replace(/\s+/g, ' '); }
function clamp(value, min, max, fallback) { const number = Number(value); return Number.isFinite(number) ? Math.min(max, Math.max(min, Math.round(number))) : fallback; }
function eventId(counter) { return `hanna-v2-${wallNow().toString(36)}-${counter.toString(36)}`; }
function asArray(value) { return Array.isArray(value) ? value : value == null ? [] : [value]; }
function formatTime(ms) { const seconds = Math.max(0, Math.ceil(ms / 1000)); return seconds >= 60 ? `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2,'0')}` : `${seconds} mp`; }
function findButton(root, label) { return [...(root.querySelectorAll?.('button') || [])].find((entry) => entry.textContent === label); }
function displayBlockTitle(block, fallback = '') { return block?.id === 'peg-feedback' ? 'A memóriahorgok gyakorlása' : block?.title || fallback; }

function loadCssOnce() {
  if (typeof document === 'undefined' || document.querySelector?.('link[data-hanna-v2-css]')) return;
  const link = document.createElement('link'); link.rel = 'stylesheet';
  link.href = new URL('./hanna-v2.css', import.meta.url).href; link.dataset.hannaV2Css = 'true'; document.head?.append(link);
}

export function shuffleHannaChoices(items, seed) {
  const out = [...items]; let state = (Number(seed) >>> 0) || 0x6d2b79f5;
  for (let index = out.length - 1; index > 0; index--) {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    const other = Math.floor((state / 4294967296) * (index + 1)); [out[index], out[other]] = [out[other], out[index]];
  }
  return out;
}

export function describeHannaSettings(settings = {}) {
  try { const described=describeFromEngine({ ...settings, hannaVersion: 2 });return String(described).replace(/\bbeginner\b/g,'Kezdő').replace(/\beasy\b/g,'Könnyű').replace(/\bnormal\b/g,'Normál').replace(/\bhard\b/g,'Nehéz').replace(/\bexpert\b/g,'Szakértő').replace(/\bitems\/min\b/g,'elem/perc'); }
  catch {
    const activity = ACTIVITY_BY_ID.get(settings.activity) || HANNA_ACTIVITIES[0];
    return `${activity?.title || 'Hanna Módszer'} · ${settings.itemCount || 'rövid'} tétel · ${DIFFICULTY.find(([id]) => id === settings.difficulty)?.[1] || 'kezdő'}`;
  }
}

function option(h, value, label, selected) { return h('option', { value, selected: String(value) === String(selected) }, label); }
function field(h, label, control, help = '') { return h('label', { className: 'hanna-v2-field' }, h('span', {}, label), control, help ? h('small', {}, help) : null); }

function normalizeDraft(raw) {
  const activity = ACTIVITY_BY_ID.has(raw.activity) ? raw.activity : HANNA_ACTIVITIES[0]?.id || 'baseline';
  const capabilities = hannaActivityCapabilities(activity);
  const active = new Set(capabilities.activeSettings);
  const counts = COUNT_BY_ACTIVITY[activity] || [5,10,20];
  const contents = CONTENT_BY_ACTIVITY[activity] || [];
  const recalls = capabilities.recallModes || [];
  const encodingActive = active.has('encodingMs') && !['association','concept','random','review'].includes(activity);
  const difficulty = DIFFICULTY.some(([id]) => id === raw.difficulty) ? raw.difficulty : 'beginner';
  let normalized=null;try{normalized=normalizeHannaSettings({...raw,hannaVersion:2,activity});}catch{}
  const requestedCount=Number(raw.itemCount??normalized?.itemCount);const derivedCount=Number(normalized?.itemCount);
  const itemCount=active.has('itemCount')?(Number.isFinite(derivedCount)?derivedCount:counts.includes(requestedCount)?requestedCount:counts[0]):Number.isFinite(derivedCount)?derivedCount:undefined;
  const encodingMs=[0,30000,60000,120000].includes(Number(raw.encodingMs??normalized?.encodingMs))?Number(raw.encodingMs??normalized?.encodingMs):0;
  const adaptive=raw.adaptive===true||raw.adaptive==='true';
  return {
    hannaVersion: 2, activity,
    difficulty,
    ...(Number.isFinite(itemCount)?{itemCount}:{}),
    ...(encodingActive?{encodingMs}:{}),
    ...(active.has('adaptive')?{adaptive}:{}),
    ...(active.has('contentLevel')&&contents.length ? { contentLevel: contents.includes(raw.contentLevel) ? raw.contentLevel : contents[0] } : {}),
    ...(active.has('recallMode')&&recalls.length ? { recallMode: recalls.includes(raw.recallMode) ? raw.recallMode : recalls[0] } : {}),
    ...(active.has('delayMs') ? { delayMs: difficulty === 'expert' ? 300000 : [10000,60000,300000].includes(Number(raw.delayMs)) ? Number(raw.delayMs) : difficulty === 'hard' ? 60000 : 10000 } : {}),
    ...(activity === 'association' ? { associationMs: Number(raw.associationMs) === 60000 ? 60000 : 30000 } : {}),
    ...(active.has('trainingSize') ? { trainingSize: [10,20,100].includes(Number(raw.trainingSize)) ? Number(raw.trainingSize) : counts[0] } : {}),
    ...(active.has('similarity') ? { similarity: raw.similarity === 'similar' ? 'similar' : 'varied' } : {}),
    ...(active.has('interferenceLevel') ? { interferenceLevel: [0,1,2].includes(Number(raw.interferenceLevel)) ? Number(raw.interferenceLevel) : 0 } : {}),
  };
}

