    const activity = ACTIVITY_BY_ID.get(draft.activity); const capabilities=hannaActivityCapabilities(draft.activity);const active=new Set(capabilities.activeSettings);const encodingActive=active.has('encodingMs')&&!['association','concept','random','review'].includes(draft.activity);const counts = COUNT_BY_ACTIVITY[draft.activity] || [5]; const countOptions=[...new Set([...(Number.isFinite(Number(draft.itemCount))?[Number(draft.itemCount)]:[]),...counts])].sort((a,b)=>a-b);const content = CONTENT_BY_ACTIVITY[draft.activity] || []; const recalls = capabilities.recallModes || [];
