    if(focusedSetting)globalThis.requestAnimationFrame?.(()=>{const target=[...(element.querySelectorAll?.('[data-setting]')||[])].find((node)=>node.dataset?.setting===focusedSetting);try{target?.focus?.({preventScroll:true});}catch{target?.focus?.();}});
