  function resourcePicker(){const setting=RESOURCE_FOR_ACTIVITY[draft.activity];if(!setting)return null;const kinds=asArray(setting);if(resourceState==='loading')return h('div',{className:'hanna-v2-inline-status',role:'status'},'Saját eszközök betöltése…');if(resourceState==='error')return h('div',{className:'hanna-v2-inline-error',role:'alert'},h('span',{},resourceError),h('button',{type:'button',onClick:loadResources},'Újrapróbálom'));if(resourceState==='guest')return h('p',{className:'hanna-v2-field-help'},`Belépés után saját ${kinds.map((kind)=>RESOURCE_LABEL[kind]).join(' és ')} is választható.`);return kinds.map(resourceField);}
