function safeVisual(item, fallback = 'memory') {
  if (item?.visual) return item.visual;
  if (item?.portraitId) return { type: 'portrait', key: item.portraitId, label: item.label };
  if (item?.kind === 'number' || /^\d+$/.test(String(item?.label || ''))) return { type: 'number', key: item?.id, label: item?.label };
  return { type: item?.kind === 'concept' ? 'concept' : 'object', key: item?.id || fallback, label: item?.label };
}

function buildFallbackFlow(plan) {
  const flow = [{id:'instruction',phase:'instruction',title:'Hogyan dolgozunk?'}];
  if (plan.training) flow.push({id:'training',phase:'training',title:'Betanítás'});
  if (plan.encodingSteps?.length) flow.push({id:'encoding',phase:'encoding',title:'Kapcsolatok építése',stepIds:plan.encodingSteps.map((entry)=>entry.id)});
  flow.push({id:'recall',phase:'recall',title:'Felidézés',trialIds:(plan.recallTrials||[]).map((entry)=>entry.id)}); return flow;
}

